fields.InputDefinition:
{
  "goal": "Switch to the Admin application via the application switcher dropdown next to the logo, open 'Identity & Access', and select the 'Users' sub-section. Then walk these controls IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) users-bulk-selection — click the selection checkbox on one or two user rows (or the 'Select All' checkbox in the header) and confirm a contextual bulk-action toolbar appears showing the selected count and buttons for Enable, Disable, Assign Role, and Delete plus a Clear control; then click 'Clear' and confirm the bulk toolbar disappears (do NOT execute any bulk action); (2) users-filter-popover — click the 'Filters' button in the header card to open the filter panel, apply a Status (Active/Inactive) or Role filter, and confirm the users list narrows to matching rows (or shows a valid no-results state) with the X-of-Y count badge and applied-filter indicator updating; then clear the filters and confirm the full list returns; (3) users-card-expand — click a user card header (not its checkbox) to expand it and confirm the expanded panel reveals a stats section (Type, Full Name, Created, Updated) and an 'Assigned Roles' section listing the user's roles (or a 'No roles assigned' message); click the header again to collapse it. Keep going until every control has been exercised. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "users-bulk-selection",
      "instruction": "select users and use the bulk toolbar",
      "visualCriteria": [
        "Selecting one or more users via the row checkboxes (or Select All) reveals a bulk-action toolbar with a selection count and Enable / Disable / Assign Role / Delete buttons, and clicking Clear removes the bulk-action toolbar"
      ]
    },
    {
      "name": "users-filter-popover",
      "instruction": "filter the users list via the popover",
      "visualCriteria": [
        "Opening the 'Filters' popover and applying a status or role filter narrows the Users list to matches (or shows a valid no-results empty state) and updates the X-of-Y count badge, and clearing the filters restores the unfiltered list"
      ]
    },
    {
      "name": "users-card-expand",
      "instruction": "expand a user card to show details and roles",
      "visualCriteria": [
        "Clicking a user card header expands it to reveal a stats section (Type / Full Name / Created / Updated) and an 'Assigned Roles' section (roles list or 'No roles assigned'), and clicking the header again collapses the card"
      ]
    }
  ]
}
